// Parking spot state per zone (SceneScape scene) and slot (region); emits one InfluxDB point per known slot.
// Inputs: retained slot lists, per-zone vehicle stream, slot (region) events, and a periodic tick.
const spots = flow.get('spots') || {};
const rois = flow.get('rois') || {};          // scene uid -> [slot names]
const sceneNames = flow.get('sceneNames') || {};
const attrs = flow.get('attrs') || {};        // tracked object id -> {type, color, seen}
const now = Date.now();
const ATTR_TTL_MS = 120000;
const pad = n => String(n).padStart(2, '0');
const fmtTime = ms => { const d = new Date(ms); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`; };
// 'Smart-Parking-Zone1' -> '1', 'Slot3' -> '3', matching the numeric IDs of the default dashboard
const idOf = name => (String(name).match(/(\d+)$/) || [])[1] || String(name);
const fmtDur = s => { s = Math.max(0, Math.floor(s)); return `${pad(Math.floor(s / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`; };
const topic = msg.topic || '';

function seed(uid) {
    const name = sceneNames[uid];
    (rois[uid] || []).forEach(slot => {
        const key = `${name}/${slot}`;
        if (name && !spots[key]) {
            spots[key] = { zone: idOf(name), spot: idOf(slot), occupied: false };
        }
    });
}

if (topic.startsWith('scenescape/data/child/rois/')) {
    const uid = topic.split('/').pop();
    rois[uid] = (Array.isArray(msg.payload) ? msg.payload : []).map(r => r.title);
    seed(uid);
} else if (topic.startsWith('scenescape/data/scene/')) {
    const uid = topic.split('/')[3];
    if (msg.payload && msg.payload.name && !sceneNames[uid]) {
        sceneNames[uid] = msg.payload.name;
        seed(uid);
    }
    ((msg.payload && msg.payload.objects) || []).forEach(o => {
        const a = attrs[o.id] || {};
        attrs[o.id] = { type: o.vehicle_type || a.type, color: o.color || a.color, seen: now };
    });
    Object.keys(attrs).forEach(id => { if (now - attrs[id].seen > ATTR_TTL_MS) delete attrs[id]; });
    flow.set('attrs', attrs);
} else if (topic.startsWith('scenescape/event/region/')) {
    const p = msg.payload;
    if (!p || !p.scene_name || !p.region_name) {
        return null;
    }
    sceneNames[p.scene_id] = p.scene_name;
    const key = `${p.scene_name}/${p.region_name}`;
    const spot = spots[key] || { zone: idOf(p.scene_name), spot: idOf(p.region_name), occupied: false };
    const vehicles = (p.objects || []).filter(o => o.category === 'vehicle');
    if (vehicles.length > 0) {
        if (!spot.occupied) {
            spot.occupied = true;
            spot.entry = Date.parse(p.timestamp) || now;
        }
        spot.objId = vehicles[0].id;
        const a = vehicles.map(o => attrs[o.id]).find(x => x) || {};
        spot.type = a.type || spot.type;
        spot.color = a.color || spot.color;
    } else {
        spot.occupied = false;
        spot.entry = null;
        spot.objId = null;
        spot.type = '';
        spot.color = '';
    }
    spots[key] = spot;
}
flow.set('spots', spots);
flow.set('rois', rois);
flow.set('sceneNames', sceneNames);

if (topic !== 'tick') {
    return null;
}
// Fill Type/Color for occupied slots whose attributes arrived after the region event
Object.values(spots).forEach(s => {
    const a = s.occupied && s.objId && attrs[s.objId];
    if (a) {
        s.type = s.type || a.type;
        s.color = s.color || a.color;
    }
});
const points = Object.values(spots).map(s => [
    {
        status: s.occupied ? 'Occupied' : 'Empty',
        occupied: s.occupied ? 1 : 0,
        // Never write empty strings: they are dropped when InfluxDB results are returned as CSV, shifting table rows
        type: s.type || '-',
        color: s.color || '-',
        entry_time: s.entry ? fmtTime(s.entry) : '-',
        dwell_time: s.entry ? fmtDur((now - s.entry) / 1000) : '00:00:00',
        time: new Date(now)
    },
    { zone: s.zone, spot: s.spot }
]);
if (points.length === 0) {
    return null;
}
return { measurement: 'parking_spot', payload: points };
